mod memory;

use clap::{Parser, Subcommand};
use rusqlite::params;
use rusqlite::OptionalExtension;
use serde_json::json;
use std::io::IsTerminal;

// ---------------------------------------------------------------------------
// Output helpers
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq)]
enum OutputMode {
    Human,
    Json,
}

#[derive(Debug, Clone, Copy)]
struct OutputCtx {
    mode: OutputMode,
    color: bool,
}

impl OutputCtx {
    fn new(mode: OutputMode) -> Self {
        let color = mode == OutputMode::Human
            && std::io::stdout().is_terminal()
            && std::env::var("TERM").unwrap_or_default() != "dumb";
        Self { mode, color }
    }

    fn is_json(self) -> bool {
        self.mode == OutputMode::Json
    }
}

fn paint(out: OutputCtx, code: &str, text: &str) -> String {
    if out.color {
        format!("\x1b[{code}m{text}\x1b[0m")
    } else {
        text.to_string()
    }
}

fn truncate_text(text: &str, max_len: usize) -> String {
    if text.len() <= max_len {
        text.to_string()
    } else {
        format!("{}...", &text[..max_len])
    }
}

// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

#[derive(Parser, Debug)]
#[command(name = "imi-memory", about = "Automatic memory layer for AI agents")]
struct Cli {
    #[arg(long, global = true, help = "Output JSON")]
    json: bool,
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Watch AI session files and index them into sessions.db
    Watch {
        #[arg(long, default_value_t = 30)]
        scan_interval: u64,
