#![allow(dead_code)]

use crate::memory::memory::{self, generate_memory_delta, init_memories_table};
use crate::memory::types::canonical_project;
use serde_json::{json, Value};
use std::env;
use std::fs;
use std::io::{self, Read};
use std::path::PathBuf;

// ---------------------------------------------------------------------------
// Budget constants
// ---------------------------------------------------------------------------

const SESSION_START_BUDGET: usize = 4096;
const MID_SESSION_BUDGET: usize = 4096;
const PRE_TOOL_BUDGET: usize = 4096;

// ---------------------------------------------------------------------------
// Hook event types (from Claude Code hooks spec)
// ---------------------------------------------------------------------------

#[derive(Debug)]
enum HookEvent {
    SessionStart,
    SessionEnd,
    UserPromptSubmit,
    PreToolUse,
    PostToolUse,
    Stop,
    Unknown(String),
}

impl HookEvent {
    fn from_str(s: &str) -> Self {
        match s {
            "session_start" => HookEvent::SessionStart,
            "SessionStart" => HookEvent::SessionStart,
            "session_end" => HookEvent::SessionEnd,
            "SessionEnd" => HookEvent::SessionEnd,
            "user_prompt_submit" => HookEvent::UserPromptSubmit,
            "UserPromptSubmit" => HookEvent::UserPromptSubmit,
            "pre_tool_use" => HookEvent::PreToolUse,
            "PreToolUse" => HookEvent::PreToolUse,
            "post_tool_use" => HookEvent::PostToolUse,
            "PostToolUse" => HookEvent::PostToolUse,
            "stop" => HookEvent::Stop,
            "Stop" => HookEvent::Stop,
            other => HookEvent::Unknown(other.to_string()),
        }
    }
}

// ---------------------------------------------------------------------------
// Session start time tracking
// ---------------------------------------------------------------------------

fn session_start_marker_path() -> PathBuf {
    let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
    PathBuf::from(home).join(".imi").join("session_start_ms")
}

fn injection_tracker_path() -> PathBuf {
    let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
    PathBuf::from(home).join(".imi").join("injection_count")
}

fn read_injection_count() -> u32 {
    fs::read_to_string(injection_tracker_path())
        .ok()
        .and_then(|s| s.trim().parse().ok())
        .unwrap_or(0)
}

fn write_injection_count(count: u32) {
    let path = injection_tracker_path();
    if let Some(parent) = path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    let _ = fs::write(path, count.to_string());
}

fn reset_injection_count() {
    let _ = fs::remove_file(injection_tracker_path());
}

fn record_session_start() {
    let path = session_start_marker_path();
    if let Some(parent) = path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    let now = crate::memory::types::now_ms();
    let _ = fs::write(path, now.to_string());
    reset_injection_count();
}

fn session_duration_minutes() -> f64 {
    let start_ms: i64 = fs::read_to_string(session_start_marker_path())
        .ok()
        .and_then(|s| s.trim().parse().ok())
        .unwrap_or(0);
    if start_ms == 0 {
        return 0.0;
    }
    let now = crate::memory::types::now_ms();
    ((now - start_ms).max(0) as f64) / 60_000.0
}

// ---------------------------------------------------------------------------
// Project detection from hook input
// ---------------------------------------------------------------------------

fn extract_project(input: &Value) -> Option<String> {
    // Try all known cwd locations across tools:
    // Claude Code: cwd / workingDirectory (top-level)
    // Copilot:     data.context.cwd
    // Cursor:      workingDirectory / rootPath
    // Codex:       cwd
    let candidates: Vec<Option<&str>> = vec![
        input.get("cwd").and_then(|v| v.as_str()),
        input.get("workingDirectory").and_then(|v| v.as_str()),
        input.get("rootPath").and_then(|v| v.as_str()),
        input
            .get("data")
            .and_then(|d| d.get("context"))
            .and_then(|c| c.get("cwd"))
            .and_then(|v| v.as_str()),
        input
            .get("data")
            .and_then(|d| d.get("cwd"))
            .and_then(|v| v.as_str()),
    ];

    for cwd in candidates.into_iter().flatten() {
        if !cwd.is_empty() {
            return Some(canonical_project(cwd));
        }
    }

    // Env vars set by various tools
    for var in &["CLAUDE_PROJECT_DIR", "CURSOR_PROJECT_DIR", "COPILOT_PROJECT_DIR"] {
        if let Ok(p) = env::var(var) {
            if !p.trim().is_empty() {
                return Some(canonical_project(&p));
            }
        }
    }

    // Last resort: current working directory
    if let Ok(cwd) = env::current_dir() {
        return Some(canonical_project(&cwd.to_string_lossy()));
    }

    None
}

// ---------------------------------------------------------------------------
// Handlers
// ---------------------------------------------------------------------------

fn handle_session_start(input: &Value) -> Value {
    record_session_start();

    let project = match extract_project(input) {
        Some(p) => p,
        None => return empty_response(),
    };

    let sconn = match crate::memory::db::open_sessions_db() {
        Ok(c) => c,
        Err(_) => return empty_response(),
    };

    let _ = init_memories_table(&sconn);

    // Run indexer + compress to ensure we have fresh data
    let _ = crate::memory::indexer::run_indexer(300);
    let _ = crate::memory::compress::compress_all_pending(20);

    let brief = crate::memory::context::generate_memory_context(&sconn, &project)
        .unwrap_or_else(|_| "No session history available.".to_string());

    let brief = truncate_bytes(&brief, SESSION_START_BUDGET);

    json!({
        "additionalContext": brief
    })
}

fn handle_session_end(input: &Value) -> Value {
    let _ = crate::memory::indexer::run_indexer(300);
    let _ = crate::memory::compress::compress_all_pending(50);

    // Auto-persist outcome: read most recent session insight, adapt memory weights
    if let Ok(conn) = crate::memory::db::open_sessions_db() {
        let project = extract_project(input).unwrap_or_default();
        // Get the most recent session insight for this project
        let outcome: Option<(bool, i64)> = conn
            .query_row(
                "SELECT task_completed, json_array_length(failures_observed_json) FROM session_insights
                 WHERE project = ?1 ORDER BY generated_at_ms DESC LIMIT 1",
                rusqlite::params![project],
                |r| Ok((r.get::<_, bool>(0)?, r.get::<_, i64>(1)?)),
            )
            .ok();

        if let Some((task_completed, failure_count)) = outcome {
            let positive = task_completed && failure_count == 0;
            // Adapt weights of memories accessed in the last session
            let mem_ids: Vec<i64> = conn
                .prepare(
                    "SELECT id FROM memories WHERE env_id = ?1
                     AND last_accessed > ?2 ORDER BY last_accessed DESC LIMIT 20",
                )
                .and_then(|mut s| {
                    let cutoff = crate::memory::types::now_ms() - 90 * 60 * 1000;
                    s.query_map(rusqlite::params![project, cutoff], |r| r.get(0))
                        .map(|rows| rows.filter_map(|r| r.ok()).collect())
                })
                .unwrap_or_default();

            for id in mem_ids {
                let _ = crate::memory::memory::update_retrieval_weight_on_outcome(
                    &conn, id, positive,
                );
            }
        }

        let _ = crate::memory::memory::compress_patterns(&conn);
    }

    let _ = fs::remove_file(session_start_marker_path());
    empty_response()
}

fn handle_post_tool_use(input: &Value) -> Value {
    // Only trigger on errors/failures (works for any tool's JSON shape)
    if !extract_is_error(input) {
        return empty_response();
    }

    let project = match extract_project(input) {
        Some(p) => p,
        None => return empty_response(),
    };

    let sconn = match crate::memory::db::open_sessions_db() {
        Ok(c) => c,
        Err(_) => return empty_response(),
    };

    let _ = init_memories_table(&sconn);

    let base_query = build_tool_query(input);
    let query = if base_query.is_empty() {
        "error failure".to_string()
    } else {
        format!("{base_query} error")
    };

    // Pure BM25 — no embedding model load
    let hits = query_bm25_fast(&sconn, &query, &project, 3);
    if hits.is_empty() {
        return empty_response();
    }

    let lines: Vec<String> = hits
        .iter()
        .map(|(what, status)| format!("- [{status}] {}", truncate_bytes(what, 100)))
        .collect();

    let context_text = truncate_bytes(
        &format!("IMI context (tool error):\n{}", lines.join("\n")),
        MID_SESSION_BUDGET,
    );

    json!({ "systemMessage": context_text })
}

fn handle_user_prompt_submit(input: &Value) -> Value {
    let duration = session_duration_minutes();

    let project = match extract_project(input) {
        Some(p) => p,
        None => return empty_response(),
    };

    let sconn = match crate::memory::db::open_sessions_db() {
        Ok(c) => c,
        Err(_) => return empty_response(),
    };

    let _ = init_memories_table(&sconn);

    // Lightweight context refresh — just the delta brief
    let brief = generate_memory_delta(&sconn, &project, None, 0).unwrap_or_default();

    if brief.is_empty() || brief == "No recent activity." {
        return empty_response();
    }

    let context_text = format!("IMI mid-session refresh ({}m elapsed):\n{}", duration as i32, truncate_bytes(&brief, MID_SESSION_BUDGET));

    json!({
        "systemMessage": context_text
    })
}

fn handle_stop(input: &Value) -> Value {
    let project = match extract_project(input) {
        Some(p) => p,
        None => return empty_response(),
    };

    let sconn = match crate::memory::db::open_sessions_db() {
        Ok(c) => c,
        Err(_) => return empty_response(),
    };

    // Check for unresolved risks
    let has_risks: bool = sconn
        .query_row(
            "SELECT COUNT(*) FROM session_insights
             WHERE project = ?1
               AND json_array_length(files_at_risk_json) > 0
               AND generated_at_ms > ?2
               AND task_completed = 0",
            rusqlite::params![
                project,
                crate::memory::types::now_ms() - 30 * 60 * 1000 // last 30 min
            ],
            |r| r.get::<_, i64>(0),
        )
        .map(|c| c > 0)
        .unwrap_or(false);

    let has_recent_errors: bool = sconn
        .query_row(
            "SELECT COUNT(*) FROM session_insights
             WHERE project = ?1
               AND json_array_length(failures_observed_json) > 0
               AND generated_at_ms > ?2",
            rusqlite::params![
                project,
                crate::memory::types::now_ms() - 30 * 60 * 1000
            ],
            |r| r.get::<_, i64>(0),
        )
        .map(|c| c > 0)
        .unwrap_or(false);

    if has_risks || has_recent_errors {
        let reason = if has_risks {
            "IMI: There are files at risk or unresolved failures in this session. Consider running tests or verifying changes before stopping."
        } else {
            "IMI: There are unresolved errors from this session. Consider addressing them before stopping."
        };
        json!({
            "decision": "block",
            "reason": reason
        })
    } else {
        empty_response()
    }
}

fn handle_pre_tool_use(input: &Value) -> Value {
    let query = build_tool_query(input);
    if query.is_empty() {
        return empty_response();
    }

    let project = match extract_project(input) {
        Some(p) => p,
        None => return empty_response(),
    };

    let sconn = match crate::memory::db::open_sessions_db_readonly() {
        Ok(c) => c,
        Err(_) => return empty_response(),
    };

    // Full classifier: BM25 + semantic RRF + composite scoring (recency × truth ×
    // project boost × retrieval weight) + causal patterns + exposure tracking.
    // Embedding is disabled in hooks mode so semantic pass silently falls back to
    // BM25-only — scoring pipeline still runs in full.
    let is_first = read_injection_count() == 0;
    let result = crate::memory::classifier::classify(&sconn, &query, &project, is_first);

    // Knowledge graph edges — graph relationships the classifier doesn't cover
    let kg_hits = crate::memory::knowledge::query_with_edges(&sconn, &query, &project, 2);

    if result.context.is_none() && kg_hits.is_empty() {
        return empty_response();
    }

    let mut ctx = result.context.unwrap_or_default();

    if !kg_hits.is_empty() {
        ctx.push_str("\n<imi_kg>\n");
        for line in &kg_hits {
            ctx.push_str(&format!("- {line}\n"));
        }
        ctx.push_str("</imi_kg>");
    }

    let ctx = truncate_bytes(&ctx, PRE_TOOL_BUDGET);

    write_injection_count(read_injection_count() + 1);

    json!({ "additionalContext": ctx })
}

// ---------------------------------------------------------------------------
// Universal input normalization
//
// Different coding tools send different JSON shapes. These helpers extract
// the same logical values regardless of which tool fired the hook.
//
// Supported formats:
//   Claude Code  — tool_name, tool_input.{file_path,path,command}, cwd
//   Copilot      — toolName, data.arguments.{path,file,command}, data.context.cwd
//   Cursor       — tool, input.{file,path}, workingDirectory
//   Codex        — name, parameters.{file,path,code}, cwd
//   Generic      — any nesting of tool/name + file/path keys
// ---------------------------------------------------------------------------

/// Extract tool name from any known JSON shape.
fn extract_tool_name(input: &Value) -> String {
    // Direct top-level keys (various casings)
    for key in &["tool_name", "toolName", "tool", "name"] {
        if let Some(s) = input.get(*key).and_then(|v| v.as_str()) {
            if !s.is_empty() {
                return s.to_string();
            }
        }
    }
    // Nested under "data" (Copilot)
    if let Some(data) = input.get("data") {
        for key in &["toolName", "tool_name", "name"] {
            if let Some(s) = data.get(*key).and_then(|v| v.as_str()) {
                if !s.is_empty() {
                    return s.to_string();
                }
            }
        }
    }
    String::new()
}

/// Extract a file path hint from any known JSON shape.
fn extract_file_from_input(input: &Value) -> String {
    // Candidate containers to search, in priority order
    let containers: Vec<Option<&Value>> = vec![
        input.get("tool_input"),          // Claude Code PreToolUse
        input.get("tool_result"),         // Claude Code PostToolUse
        input.get("input"),               // Cursor
        input.get("parameters"),          // Codex
        input.get("data").and_then(|d| d.get("arguments")), // Copilot
        input.get("data"),                // Copilot fallback
        Some(input),                      // top-level fallback
    ];

    let path_keys = ["file_path", "filePath", "path", "file", "filename", "uri"];

    for container in containers.into_iter().flatten() {
        for key in &path_keys {
            if let Some(s) = container.get(*key).and_then(|v| v.as_str()) {
                if !s.is_empty() && (s.contains('/') || s.contains('.')) {
                    return s.to_string();
                }
            }
        }
    }
    String::new()
}

/// Extract a shell command string (for Bash-like tools).
fn extract_command_from_input(input: &Value) -> String {
    let containers: Vec<Option<&Value>> = vec![
        input.get("tool_input"),
        input.get("input"),
        input.get("parameters"),
        input.get("data").and_then(|d| d.get("arguments")),
        Some(input),
    ];

    let cmd_keys = ["command", "cmd", "script", "code", "query"];

    for container in containers.into_iter().flatten() {
        for key in &cmd_keys {
            if let Some(s) = container.get(*key).and_then(|v| v.as_str()) {
                let s = s.trim();
                if !s.is_empty() {
                    // Return first 120 chars — enough for FTS, not a memory dump
                    return s.chars().take(120).collect();
                }
            }
        }
    }
    String::new()
}

/// Build a classifier query from tool context. Returns empty string if there's
/// nothing useful to query on (→ skip injection for this tool call).
fn build_tool_query(input: &Value) -> String {
    let tool = extract_tool_name(input);
    let file = extract_file_from_input(input);
    let cmd = extract_command_from_input(input);

    // Prefer file stem — full paths and long commands are too specific for FTS
    let file_stem = if !file.is_empty() {
        file.rsplit('/')
            .find(|s| !s.is_empty())
            .unwrap_or(&file)
            .split('.')
            .next()
            .unwrap_or(&file)
            .to_string()
    } else {
        String::new()
    };

    // First meaningful token from a command (skip flags/paths)
    let cmd_token: String = cmd
        .split_whitespace()
        .find(|t| !t.starts_with('-') && !t.starts_with('/') && t.len() >= 3)
        .unwrap_or("")
        .to_string();

    let parts: Vec<&str> = [tool.as_str(), file_stem.as_str(), cmd_token.as_str()]
        .iter()
        .filter(|s| !s.is_empty())
        .copied()
        .collect();

    parts.join(" ")
}

/// Detect a tool error from any known JSON shape.
fn extract_is_error(input: &Value) -> bool {
    // Claude Code: tool_result.success = false
    if let Some(false) = input
        .get("tool_result")
        .and_then(|r| r.get("success"))
        .and_then(|v| v.as_bool())
    {
        return true;
    }
    // Copilot: data.success = false
    if let Some(false) = input
        .get("data")
        .and_then(|d| d.get("success"))
        .and_then(|v| v.as_bool())
    {
        return true;
    }
    // Generic: top-level success / error / isError
    if let Some(false) = input.get("success").and_then(|v| v.as_bool()) {
        return true;
    }
    if input.get("error").and_then(|v| v.as_str()).is_some() {
        return true;
    }
    if let Some(true) = input.get("isError").and_then(|v| v.as_bool()) {
        return true;
    }
    // Scan output/stderr text for error signals across all known locations
    let texts: Vec<Option<&str>> = vec![
        input.get("tool_result").and_then(|r| r.get("output")).and_then(|v| v.as_str()),
        input.get("data").and_then(|d| d.get("result")).and_then(|r| r.get("content")).and_then(|v| v.as_str()),
        input.get("output").and_then(|v| v.as_str()),
        input.get("stderr").and_then(|v| v.as_str()),
    ];
    for text in texts.into_iter().flatten() {
        let lower = text.to_lowercase();
        if lower.contains("error:") || lower.contains("failed") || lower.contains("panic") {
            return true;
        }
    }
    false
}

/// Pure BM25/FTS5 memory query — no embedding model, always fast (<10ms).
/// Returns (what, truth_status) tuples for the top hits.
fn query_bm25_fast(
    conn: &rusqlite::Connection,
    query: &str,
    project: &str,
    limit: usize,
) -> Vec<(String, String)> {
    // Strip FTS5 special chars and short tokens
    let safe_query: String = query
        .chars()
        .map(|c| if "\"(){}[]^*:".contains(c) { ' ' } else { c })
        .collect::<String>()
        .split_whitespace()
        .filter(|w| w.len() >= 2)
        .collect::<Vec<_>>()
        .join(" ");
    if safe_query.is_empty() {
        return vec![];
    }
    let sql = "
        SELECT m.what, m.truth_status
        FROM memories_fts fts
        JOIN memories m ON m.id = fts.rowid
        WHERE memories_fts MATCH ?1
          AND m.env_id = ?2
          AND m.truth_status NOT IN ('invalidated', 'superseded')
          AND m.action_type != 'session_summary'
        ORDER BY bm25(memories_fts)
        LIMIT ?3
    ";
    conn.prepare(sql)
        .ok()
        .and_then(|mut s| {
            s.query_map(rusqlite::params![safe_query, project, limit as i64], |row| {
                Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
            })
            .ok()
            .map(|rows| rows.filter_map(|r| r.ok()).collect())
        })
        .unwrap_or_default()
}

fn empty_response() -> Value {
    json!({})
}

fn truncate_bytes(s: &str, max_bytes: usize) -> String {
    if s.len() <= max_bytes {
        return s.to_string();
    }
    if max_bytes <= 3 {
        return "...".to_string();
    }
    let budget = max_bytes - 3;
    let mut out = String::new();
    for ch in s.chars() {
        if out.len() + ch.len_utf8() > budget {
            break;
        }
        out.push(ch);
    }
    out.push_str("...");
    out
}

// ---------------------------------------------------------------------------
// Main entry point
// ---------------------------------------------------------------------------

/// Read a Claude Code hook event from stdin and return the appropriate
/// response JSON on stdout.
///
/// `cli_event` overrides the JSON-body event_type detection. This is needed
/// because Claude Code hooks determine event type by which hook array
/// entry fires the command — the event type is NOT in the JSON body.
pub fn run_hook_handler(cli_event: Option<&str>) -> Result<(), String> {
    // Disable embed model for all hook paths — hooks must never download models.
    crate::memory::embed::disable_for_hooks();

    let mut input_str = String::new();
    io::stdin()
        .read_to_string(&mut input_str)
        .map_err(|e| format!("hook-handler stdin read: {e}"))?;

    let input: Value = if input_str.trim().is_empty() {
        json!({})
    } else {
        serde_json::from_str(&input_str).unwrap_or(json!({}))
    };

    // CLI arg takes priority over JSON body (Claude Code doesn't send event_type in JSON)
    let event_type = if let Some(evt) = cli_event {
        evt
    } else {
        input
            .get("hook_event_name")  // Claude Code v1.0.27+ sends this
            .or_else(|| input.get("event_type"))
            .or_else(|| input.get("type"))
            .or_else(|| input.get("hookEvent"))
            .and_then(|v| v.as_str())
            .unwrap_or("")
    };

    let event = HookEvent::from_str(event_type);

    let response = match event {
        HookEvent::SessionStart => handle_session_start(&input),
        HookEvent::SessionEnd => handle_session_end(&input),
        HookEvent::PostToolUse => handle_post_tool_use(&input),
        HookEvent::UserPromptSubmit => handle_user_prompt_submit(&input),
        HookEvent::Stop => handle_stop(&input),
        HookEvent::PreToolUse => handle_pre_tool_use(&input),
        HookEvent::Unknown(_) => empty_response(),
    };

    // Only output non-empty responses — silent no-ops produce no stdout
    if response != json!({}) {
        println!("{}", serde_json::to_string(&response).unwrap_or_default());
    }

    Ok(())
}

