#!/usr/bin/env bun
"use strict";

import * as https from "https";
import { execSync, spawnSync } from "child_process";
import { existsSync, mkdirSync, chmodSync, unlinkSync, createWriteStream, readFileSync, writeFileSync } from "fs";
import { join } from "path";
import { homedir, tmpdir, platform, arch } from "os";
import { IncomingMessage } from "http";

const pkg = JSON.parse(readFileSync(new URL("./package.json", import.meta.url).pathname, "utf8")) as { version: string };
const VERSION: string = pkg.version;
const REPO = "ProjectAI00/imi-agent";
const BIN_DIR = join(homedir(), ".local", "bin");
const BIN = join(BIN_DIR, "imi-memory");
const IMI_DIR = join(homedir(), ".imi");
const PLIST_LABEL = "com.imi-memory.watch";
const PLIST_PATH = join(homedir(), "Library", "LaunchAgents", `${PLIST_LABEL}.plist`);
const HOOKS_SETTINGS = join(homedir(), ".claude", "plugins", "marketplaces", "imi", ".claude", "settings.json");

function getTarget(): string {
  const p = platform();
  const a = arch();
  if (p === "darwin" && a === "arm64") return "aarch64-apple-darwin";
  if (p === "darwin" && a === "x64") return "x86_64-apple-darwin";
  if (p === "linux" && a === "x64") return "x86_64-unknown-linux-musl";
  if (p === "linux" && a === "arm64") return "aarch64-unknown-linux-musl";
  console.error(`Unsupported platform: ${p} ${a}`);
  process.exit(1);
}

function fetchBinary(url: string, dest: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const file = createWriteStream(dest);
    const req = (u: string) =>
      https.get(u, (res: IncomingMessage) => {
        if (res.statusCode === 301 || res.statusCode === 302) return req(res.headers.location as string);
        if (res.statusCode !== 200) { reject(new Error(`HTTP ${res.statusCode}`)); return; }
        res.pipe(file);
        file.on("finish", () => file.close(resolve as () => void));
      }).on("error", reject);
    req(url);
  });
}

function installBinary(): void {
  // Try downloading a release binary first
  const target = getTarget();
  const url = `https://github.com/${REPO}/releases/download/imi-memory-v${VERSION}/imi-memory-${target}.tar.gz`;
  const tmp = join(tmpdir(), `imi-memory-${Date.now()}.tar.gz`);

  process.stdout.write(`Installing imi-memory v${VERSION}... `);
  mkdirSync(BIN_DIR, { recursive: true });

  try {
    // Try release download
    execSync(`curl -fsSL "${url}" -o "${tmp}" 2>/dev/null`, { stdio: "pipe" });
    execSync(`tar -xzf "${tmp}" -C "${BIN_DIR}"`, { stdio: "pipe" });
    chmodSync(BIN, 0o755);
    unlinkSync(tmp);
    console.log("done");
  } catch {
    // Fall back to building from source
    console.log("no release found, building from source...");
    const srcDir = new URL("..", import.meta.url).pathname;
    if (!existsSync(join(srcDir, "Cargo.toml"))) {
      console.error("Cannot build: Cargo.toml not found. Install Rust or wait for a release.");
      process.exit(1);
    }
    execSync(`cargo build --release --manifest-path "${join(srcDir, "Cargo.toml")}"`, { stdio: "inherit" });
    const built = join(srcDir, "target", "release", "imi-memory");
    execSync(`cp "${built}" "${BIN}"`, { stdio: "pipe" });
    chmodSync(BIN, 0o755);
    console.log("built and installed.");
  }
}

function installDaemon(): void {
  if (platform() !== "darwin") {
    console.log("  Daemon: skipped (non-macOS — start manually: imi-memory watch)");
    return;
  }

  mkdirSync(join(homedir(), "Library", "LaunchAgents"), { recursive: true });
  mkdirSync(IMI_DIR, { recursive: true });

  const plist = `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key>
  <string>${PLIST_LABEL}</string>
  <key>ProgramArguments</key>
  <array>
    <string>${BIN}</string>
    <string>watch</string>
  </array>
  <key>RunAtLoad</key>
  <true/>
  <key>KeepAlive</key>
  <true/>
  <key>StandardOutPath</key>
  <string>${IMI_DIR}/memory-watch.log</string>
  <key>StandardErrorPath</key>
  <string>${IMI_DIR}/memory-watch.error.log</string>
</dict>
</plist>`;

  writeFileSync(PLIST_PATH, plist);

  // Unload if already running, then reload
  try { execSync(`launchctl unload "${PLIST_PATH}" 2>/dev/null`, { stdio: "pipe" }); } catch {}
  try {
    execSync(`launchctl load "${PLIST_PATH}"`, { stdio: "pipe" });
    console.log("  Daemon: started (auto-restarts on login)");
  } catch {
    console.log(`  Daemon: registered (run manually: launchctl load "${PLIST_PATH}")`);
  }
}

function installHooks(): void {
  if (!existsSync(HOOKS_SETTINGS)) {
    console.log("  Hooks: Claude Code plugin not found, skipping");
    return;
  }

  let settings: Record<string, unknown> = {};
  try { settings = JSON.parse(readFileSync(HOOKS_SETTINGS, "utf8")); } catch {}

  const hooks = (settings.hooks as Record<string, unknown[]>) ?? {};
  const MEMORY_HOOK = "imi-memory hook-handler";

  const addHook = (event: string, command: string) => {
    if (!hooks[event]) hooks[event] = [];
    const existing = hooks[event] as Array<{ matcher: string; hooks: Array<{ type: string; command: string }> }>;
    // Check if already registered in any hook entry
    const alreadyAdded = existing.some(entry =>
      entry.hooks?.some(h => h.command === command)
    );
    if (alreadyAdded) return;
    // Add to the catch-all matcher entry if one exists, otherwise append a new entry
    const catchAll = existing.find(e => e.matcher === "");
    if (catchAll) {
      catchAll.hooks.push({ type: "command", command });
    } else {
      existing.push({ matcher: "", hooks: [{ type: "command", command }] });
    }
  };

  addHook("SessionStart", `${MEMORY_HOOK} session_start`);
  addHook("SessionEnd", `${MEMORY_HOOK} session_end`);
  addHook("PreToolUse", `${MEMORY_HOOK} pre_tool_use`);
  addHook("PostToolUse", `${MEMORY_HOOK} post_tool_use`);
  addHook("UserPromptSubmit", `${MEMORY_HOOK} user_prompt_submit`);
  addHook("Stop", `${MEMORY_HOOK} stop`);

  settings.hooks = hooks;
  writeFileSync(HOOKS_SETTINGS, JSON.stringify(settings, null, 2));
  console.log("  Hooks: registered in Claude Code");
}

function bootstrapSessions(): void {
  process.stdout.write("  Indexing existing sessions... ");
  try {
    const result = spawnSync(BIN, ["index-sessions"], { encoding: "utf8" });
    const out = (result.stdout ?? "").trim();
    console.log(out || "done");
  } catch {
    console.log("skipped");
  }
}

async function main(): Promise<void> {
  // If binary already installed and up to date, skip download
  if (existsSync(BIN)) {
    try {
      const v = execSync(`${BIN} --version 2>/dev/null`, { encoding: "utf8" }).trim();
      if (v.includes(VERSION)) {
        console.log(`imi-memory ${VERSION} already installed`);
        installDaemon();
        installHooks();
        return;
      }
    } catch {}
  }

  installBinary();
  installDaemon();
  installHooks();
  bootstrapSessions();

  const inPath = (process.env.PATH ?? "").split(":").includes(BIN_DIR);
  if (!inPath) {
    console.log(`\nAdd to your shell config:\n  export PATH="$HOME/.local/bin:$PATH"\n`);
  }

  console.log("\nDone. imi-memory is running silently in the background.");
}

main().catch((err: Error) => {
  console.error("Install failed:", err.message);
  process.exit(1);
});

