//! Local semantic embeddings using fastembed (BGE-Small-EN-v1.5, 384-dim).
//!
//! The model is downloaded once to `~/.cache/huggingface/` on first call and
//! reused from that point. All operations are fallible — callers must
//! gracefully degrade to BM25-only when embedding is unavailable.

use fastembed::{EmbeddingModel, InitOptions, TextEmbedding};
use std::sync::{Mutex, OnceLock};

static MODEL: OnceLock<Option<Mutex<TextEmbedding>>> = OnceLock::new();

/// Set to true from hook-handler entry point to prevent any model download.
/// Hooks must never block on network I/O.
static HOOKS_MODE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Call this before any hook handler runs. Prevents embed model initialization.
pub fn disable_for_hooks() {
    HOOKS_MODE.store(true, std::sync::atomic::Ordering::Relaxed);
}

fn model() -> Option<&'static Mutex<TextEmbedding>> {
    // Never initialize the model in hook context — it downloads from HuggingFace
    // and blocks in uninterruptible kernel sleep when network is unavailable.
    if HOOKS_MODE.load(std::sync::atomic::Ordering::Relaxed) {
        return None;
    }
    MODEL
        .get_or_init(|| {
            let opts = InitOptions::new(EmbeddingModel::BGESmallENV15).with_show_download_progress(false);
            match TextEmbedding::try_new(opts) {
                Ok(m) => Some(Mutex::new(m)),
                Err(_) => None,
            }
        })
        .as_ref()
}

/// Embed a single string. Returns `None` if the model is unavailable.
pub fn embed_one(text: &str) -> Option<Vec<f32>> {
    let m = model()?;
    let guard = m.lock().ok()?;
    guard.embed(vec![text], None).ok()?.into_iter().next()
}

/// Embed a batch of strings. Returns `None` if the model is unavailable.
pub fn embed_batch(texts: &[&str]) -> Option<Vec<Vec<f32>>> {
    let m = model()?;
    let guard = m.lock().ok()?;
    guard.embed(texts.to_vec(), None).ok()
}

/// Cosine similarity in [−1, 1]. Returns 0 on zero-length vectors.
pub fn cosine(a: &[f32], b: &[f32]) -> f32 {
    if a.len() != b.len() || a.is_empty() {
        return 0.0;
    }
    let dot: f32 = a.iter().zip(b).map(|(x, y)| x * y).sum();
    let na: f32 = a.iter().map(|x| x * x).sum::<f32>().sqrt();
    let nb: f32 = b.iter().map(|x| x * x).sum::<f32>().sqrt();
    if na == 0.0 || nb == 0.0 {
        0.0
    } else {
        dot / (na * nb)
    }
}

/// Serialize a float vector to raw little-endian bytes for SQLite BLOB storage.
pub fn serialize(v: &[f32]) -> Vec<u8> {
    v.iter().flat_map(|f| f.to_le_bytes()).collect()
}

/// Deserialize a BLOB from SQLite back to a float vector.
pub fn deserialize(bytes: &[u8]) -> Vec<f32> {
    bytes
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect()
}

